"use strict";
// Scoped package with no capabilities except an fs call, to test scoped-name attribution.
const util = require("util");
const fs = require("fs");

module.exports = {
  promisifiedExists: util.promisify(fs.exists),
  readFile: util.promisify(fs.readFile),
  readFileName: fs.readFile.name,
  readFileLength: fs.readFile.length,
};
